/* Isolated TLS/AVC420 producer; no desktop, credentials or external listener.
 * Access units are real Annex B packets generated by run_h264_test.py. */
#include <freerdp/freerdp.h>
#include <freerdp/peer.h>
#include <freerdp/listener.h>
#include <freerdp/settings.h>
#include <freerdp/input.h>
#include <freerdp/channels/wtsvc.h>
#include <freerdp/channels/channels.h>
#include <freerdp/channels/drdynvc.h>
#include <freerdp/server/rdpgfx.h>
#include <freerdp/crypto/certificate.h>
#include <freerdp/crypto/privatekey.h>
#include <winpr/wtsapi.h>
#include <winpr/synch.h>
#include <winpr/sysinfo.h>
#include <winpr/ssl.h>
#include <stdio.h>
#include <stdlib.h>
#include <inttypes.h>

#define WIDTH 320
#define HEIGHT 240
#define MAX_PACKETS 32
static const char *cert_path, *key_path;
static BOOL finished, success, caps_ready;
static unsigned packet_count;
static UINT64 initial_delay_ms = 200, frame_interval_ms = 350;
static struct { BYTE* data; UINT32 length; } packets[MAX_PACKETS];

/* Device screenshot startup can outlast the default first color group. These
 * bounded fixture-only timings do not affect application decode or its oracle. */
static BOOL timing_option(const char* name, UINT64* value) {
  const char* text = getenv(name);
  if (!text) return TRUE;
  if (*text < '0' || *text > '9') return FALSE;
  char* end = NULL;
  unsigned long parsed = strtoul(text, &end, 10);
  if (*end || parsed > 2000) return FALSE;
  *value = parsed;
  return TRUE;
}

static BOOL post_connect(freerdp_peer* peer) {
  (void)peer; return TRUE;
}
static BOOL key(rdpInput* input, UINT16 flags, UINT8 code) {
  (void)input;
  if ((flags & KBD_FLAGS_RELEASE) && code == 0x1e) {
    success = TRUE;
    puts("Input A acknowledged"); fflush(stdout);
  }
  return TRUE;
}
static UINT frame_ack(RdpgfxServerContext* gfx, const RDPGFX_FRAME_ACKNOWLEDGE_PDU* pdu) {
  (void)gfx; (void)pdu; return CHANNEL_RC_OK;
}
static UINT caps(RdpgfxServerContext* gfx, const RDPGFX_CAPS_ADVERTISE_PDU* pdu) {
  RDPGFX_CAPSET chosen = {0};
  for (UINT16 i = 0; i < pdu->capsSetCount; i++) {
    const RDPGFX_CAPSET* set = &pdu->capsSets[i];
    if ((set->version == RDPGFX_CAPVERSION_81 &&
         (set->flags & RDPGFX_CAPS_FLAG_AVC420_ENABLED)) ||
        (set->version == RDPGFX_CAPVERSION_10 &&
         !(set->flags & RDPGFX_CAPS_FLAG_AVC_DISABLED))) {
      chosen = *set; break;
    }
  }
  if (!chosen.version) return ERROR_NOT_SUPPORTED;
  RDPGFX_CAPS_CONFIRM_PDU confirm = { .capsSet = &chosen };
  UINT rc = gfx->CapsConfirm(gfx, &confirm);
  if (rc == CHANNEL_RC_OK) {
    caps_ready = TRUE;
    printf("GFX caps version=%08x flags=%08x\n", chosen.version, chosen.flags);
    fflush(stdout);
  }
  return rc;
}
static BOOL initialize_surface(RdpgfxServerContext* gfx) {
  MONITOR_DEF monitor = { .left = 0, .top = 0, .right = WIDTH - 1,
                         .bottom = HEIGHT - 1, .flags = 1 };
  RDPGFX_RESET_GRAPHICS_PDU reset = { .width = WIDTH, .height = HEIGHT,
    .monitorCount = 1, .monitorDefArray = &monitor };
  RDPGFX_CREATE_SURFACE_PDU create = { .surfaceId = 1, .width = WIDTH,
    .height = HEIGHT, .pixelFormat = GFX_PIXEL_FORMAT_XRGB_8888 };
  RDPGFX_MAP_SURFACE_TO_OUTPUT_PDU map = { .surfaceId = 1 };
  return gfx->ResetGraphics(gfx, &reset) == CHANNEL_RC_OK &&
    gfx->CreateSurface(gfx, &create) == CHANNEL_RC_OK &&
    gfx->MapSurfaceToOutput(gfx, &map) == CHANNEL_RC_OK;
}
static BOOL send_frame(RdpgfxServerContext* gfx, unsigned index) {
  RECTANGLE_16 region = { .left = 0, .top = 0, .right = WIDTH, .bottom = HEIGHT };
  RDPGFX_H264_QUANT_QUALITY quant = { .qp = 20, .qualityVal = 100 };
  RDPGFX_AVC420_BITMAP_STREAM avc = { .length = packets[index].length,
    .data = packets[index].data,
    .meta = { .numRegionRects = 1, .regionRects = &region, .quantQualityVals = &quant } };
  RDPGFX_SURFACE_COMMAND cmd = { .surfaceId = 1, .codecId = RDPGFX_CODECID_AVC420,
    .format = PIXEL_FORMAT_BGRX32, .right = WIDTH, .bottom = HEIGHT,
    .width = WIDTH, .height = HEIGHT, .extra = &avc };
  RDPGFX_START_FRAME_PDU start = { .timestamp = (UINT32)GetTickCount64(), .frameId = index + 1 };
  RDPGFX_END_FRAME_PDU end = { .frameId = index + 1 };
  const UINT rc = gfx->SurfaceFrameCommand(gfx, &cmd, &start, &end);
  printf("AVC420 frame=%u bytes=%u status=%u\n", index + 1, packets[index].length, rc);
  fflush(stdout);
  return rc == CHANNEL_RC_OK;
}
static BOOL accepted(freerdp_listener* listener, freerdp_peer* peer) {
  (void)listener;
  HANDLE vcm = NULL;
  RdpgfxServerContext* gfx = NULL;
  BOOL opened = FALSE, surface = FALSE;
  if (!freerdp_peer_context_new(peer)) { freerdp_peer_free(peer); finished = TRUE; return TRUE; }
  rdpSettings* cfg = peer->context->settings;
  rdpPrivateKey* private_key = freerdp_key_new_from_file_enc(key_path, NULL);
  rdpCertificate* cert = freerdp_certificate_new_from_file(cert_path);
  BOOL ok = private_key && cert &&
    freerdp_settings_set_pointer_len(cfg, FreeRDP_RdpServerRsaKey, private_key, 1) &&
    freerdp_settings_set_pointer_len(cfg, FreeRDP_RdpServerCertificate, cert, 1) &&
    freerdp_settings_set_bool(cfg, FreeRDP_RdpSecurity, FALSE) &&
    freerdp_settings_set_bool(cfg, FreeRDP_NlaSecurity, FALSE) &&
    freerdp_settings_set_bool(cfg, FreeRDP_TlsSecurity, TRUE) &&
    freerdp_settings_set_bool(cfg, FreeRDP_ExtSecurity, FALSE) &&
    freerdp_settings_set_bool(cfg, FreeRDP_SupportGraphicsPipeline, TRUE) &&
    freerdp_settings_set_uint32(cfg, FreeRDP_ColorDepth, 32) &&
    freerdp_settings_set_uint32(cfg, FreeRDP_DesktopWidth, WIDTH) &&
    freerdp_settings_set_uint32(cfg, FreeRDP_DesktopHeight, HEIGHT);
  peer->context->input->KeyboardEvent = key;
  peer->PostConnect = post_connect;
  if (!ok) goto cleanup;
  vcm = WTSOpenServerA((LPSTR)peer->context);
  if (!vcm || vcm == INVALID_HANDLE_VALUE) goto cleanup;
  gfx = rdpgfx_server_context_new(vcm);
  if (!gfx) goto cleanup;
  gfx->rdpcontext = peer->context;
  gfx->CapsAdvertise = caps;
  gfx->FrameAcknowledge = frame_ack;
  if (!gfx->Initialize(gfx, TRUE) || !peer->Initialize(peer)) goto cleanup;
  const UINT64 deadline = GetTickCount64() + 25000;
  UINT64 next_frame = 0;
  unsigned sent = 0;
  /* A acknowledges input without disconnecting: the client must still stop an
   * active session itself. CheckFileDescriptor exits when that socket closes. */
  while (GetTickCount64() < deadline) {
    HANDLE handles[32];
    DWORD count = peer->GetEventHandles(peer, handles, 30);
    if (!count) break;
    HANDLE channel_event = WTSVirtualChannelManagerGetEventHandle(vcm);
    HANDLE gfx_event = rdpgfx_server_get_event_handle(gfx);
    if (channel_event) handles[count++] = channel_event;
    if (gfx_event) handles[count++] = gfx_event;
    if (WaitForMultipleObjects(count, handles, FALSE, 10) == WAIT_FAILED ||
        !peer->CheckFileDescriptor(peer)) break;
    if (peer->activated && WTSVirtualChannelManagerIsChannelJoined(vcm, DRDYNVC_SVC_CHANNEL_NAME)) {
      BYTE state = WTSVirtualChannelManagerGetDrdynvcState(vcm);
      if (state == DRDYNVC_STATE_NONE && !WTSVirtualChannelManagerCheckFileDescriptor(vcm)) break;
      if (state == DRDYNVC_STATE_READY && !opened) {
        if (!gfx->Open(gfx)) break;
        opened = TRUE;
      }
      if (state == DRDYNVC_STATE_FAILED) break;
    }
    if (channel_event && WaitForSingleObject(channel_event, 0) == WAIT_OBJECT_0 &&
        !WTSVirtualChannelManagerCheckFileDescriptor(vcm)) break;
    if (gfx_event && WaitForSingleObject(gfx_event, 0) == WAIT_OBJECT_0 &&
        rdpgfx_server_handle_messages(gfx) != CHANNEL_RC_OK) break;
    if (!peer->activated || !caps_ready) continue;
    if (!surface) {
      if (!initialize_surface(gfx)) break;
      surface = TRUE;
      next_frame = GetTickCount64() + initial_delay_ms;
    }
    if (sent < packet_count && GetTickCount64() >= next_frame) {
      if (!send_frame(gfx, sent++)) break;
      next_frame = GetTickCount64() + frame_interval_ms;
      if (sent == packet_count) { puts("AVC420 final frame then silence"); fflush(stdout); }
    }
  }
cleanup:
  if (gfx) {
    if (opened) gfx->Close(gfx);
    rdpgfx_server_context_free(gfx);
  }
  if (vcm && vcm != INVALID_HANDLE_VALUE) WTSCloseServer(vcm);
  peer->Disconnect(peer); freerdp_peer_context_free(peer); freerdp_peer_free(peer);
  finished = TRUE;
  return TRUE;
}
int main(int argc, char** argv) {
  if (argc < 5 || argc - 4 > MAX_PACKETS) return 2;
  if (!timing_option("LRDP_H264_INITIAL_DELAY_MS", &initial_delay_ms) ||
      !timing_option("LRDP_H264_FRAME_INTERVAL_MS", &frame_interval_ms)) return 2;
  printf("AVC420 timing initial_ms=%" PRIu64 " interval_ms=%" PRIu64 "\n",
         initial_delay_ms, frame_interval_ms);
  fflush(stdout);
  cert_path = argv[2]; key_path = argv[3];
  packet_count = (unsigned)(argc - 4);
  for (unsigned i = 0; i < packet_count; i++) {
    FILE* f = fopen(argv[4 + i], "rb");
    if (!f || fseek(f, 0, SEEK_END)) return 2;
    long size = ftell(f);
    if (size <= 0 || size > 16 * 1024 * 1024 || fseek(f, 0, SEEK_SET)) { fclose(f); return 2; }
    packets[i].length = (UINT32)size;
    packets[i].data = malloc((size_t)size);
    if (!packets[i].data || fread(packets[i].data, 1, (size_t)size, f) != (size_t)size) {
      fclose(f); return 2;
    }
    fclose(f);
  }
  if (!winpr_InitializeSSL(WINPR_SSL_INIT_DEFAULT) ||
      !WTSRegisterWtsApiFunctionTable(FreeRDP_InitWtsApi())) return 2;
  freerdp_listener* listener = freerdp_listener_new();
  if (!listener) return 3;
  listener->PeerAccepted = accepted;
  if (!listener->Open(listener, "127.0.0.1", (UINT16)atoi(argv[1]))) return 4;
  const UINT64 deadline = GetTickCount64() + 30000;
  while (!finished && GetTickCount64() < deadline) {
    HANDLE handles[32]; DWORD count = listener->GetEventHandles(listener, handles, 32);
    if (!count || WaitForMultipleObjects(count, handles, FALSE, 50) == WAIT_FAILED ||
        !listener->CheckFileDescriptor(listener)) break;
  }
  listener->Close(listener); freerdp_listener_free(listener);
  for (unsigned i = 0; i < packet_count; i++) free(packets[i].data);
  return success ? 0 : 1;
}
